# /// script
# requires-python = ">=3.10"
# dependencies = [
#   "flask",
#   "google-api-python-client",
#   "google-auth-oauthlib",
#   "google-auth-httplib2",
# ]
# ///
"""
Inbox — a Google Inbox clone over the Gmail API.

Triage model mirrors Inbox-by-Gmail semantics on top of native Gmail labels:
  Done   = remove the INBOX label (archive)
  Pin    = STARRED label
  Snooze = remove INBOX + add "Snoozed" label; a background scheduler re-adds
           INBOX when the snooze time arrives (state in snooze.db)
  Bundles = native Gmail categories (Promotions/Social/Updates/Forums) plus a
           light keyword classifier for Travel / Purchases / Finance.

Send-to-Things builds a things:///add deep link whose notes carry a backlink
that reopens the exact thread in this app (inboxclone://thread/<id>), with a
Gmail web permalink as the fallback.
"""
import base64
import os
import re
import sqlite3
import subprocess
import threading
import time
from datetime import datetime, timezone
from email.message import EmailMessage
from email.utils import parsedate_to_datetime
from urllib.parse import quote

from flask import Flask, jsonify, redirect, render_template, request
from google.auth.transport.requests import Request
from google.oauth2.credentials import Credentials
from google_auth_oauthlib.flow import InstalledAppFlow
from googleapiclient.discovery import build

# ----------------------------------------------------------------------------
# Config
# ----------------------------------------------------------------------------
HERE = os.path.dirname(os.path.abspath(__file__))
CRED_DIR = os.path.join(HERE, "credentials")
CLIENT_SECRET = os.path.join(CRED_DIR, "client_secret.json")
TOKEN_PATH = os.path.join(CRED_DIR, "token.json")
DB_PATH = os.path.join(HERE, "snooze.db")
PORT = 5008

SCOPES = [
    "https://www.googleapis.com/auth/gmail.modify",  # read, label, archive
    "https://www.googleapis.com/auth/gmail.send",    # send / reply
]

CATEGORY_BUNDLES = {
    "CATEGORY_PROMOTIONS": "Promos",
    "CATEGORY_SOCIAL": "Social",
    "CATEGORY_UPDATES": "Updates",
    "CATEGORY_FORUMS": "Forums",
}
# Bundle display order + icons (Material icon ligatures rendered on the client)
BUNDLE_META = {
    "Travel": {"icon": "flight", "color": "#9C27B0"},
    "Purchases": {"icon": "local_offer", "color": "#795548"},
    "Finance": {"icon": "attach_money", "color": "#679F38"},
    "Social": {"icon": "people", "color": "#DB4437"},
    "Updates": {"icon": "notifications", "color": "#FF6839"},
    "Promos": {"icon": "loyalty", "color": "#00BCD4"},
    "Forums": {"icon": "forum", "color": "#3F51B5"},
}
BUNDLE_ORDER = ["Travel", "Purchases", "Finance", "Promos", "Social", "Updates", "Forums"]

# Light keyword classifiers for the Inbox-only bundles Gmail has no native label for
TRAVEL_RE = re.compile(r"\b(flight|itinerary|boarding|reservation|hotel|booking|check-?in|airline|trip|departure|gate)\b", re.I)
PURCHASE_RE = re.compile(r"\b(order|shipped|delivery|tracking|receipt|your package|dispatched|invoice|out for delivery)\b", re.I)
FINANCE_RE = re.compile(r"\b(statement|payment|invoice|balance|transaction|deposit|bank|credit card|autopay|bill is)\b", re.I)

app = Flask(__name__)
_service = None
_service_lock = threading.Lock()
_user_email = None


# ----------------------------------------------------------------------------
# Auth / service
# ----------------------------------------------------------------------------
def get_service():
    global _service, _user_email
    with _service_lock:
        if _service is not None:
            return _service
        creds = None
        if os.path.exists(TOKEN_PATH):
            creds = Credentials.from_authorized_user_file(TOKEN_PATH, SCOPES)
        if not creds or not creds.valid:
            if creds and creds.expired and creds.refresh_token:
                creds.refresh(Request())
            else:
                flow = InstalledAppFlow.from_client_secrets_file(CLIENT_SECRET, SCOPES)
                creds = flow.run_local_server(port=0, prompt="consent")
            with open(TOKEN_PATH, "w") as f:
                f.write(creds.to_json())
            os.chmod(TOKEN_PATH, 0o600)
        _service = build("gmail", "v1", credentials=creds, cache_discovery=False)
        try:
            _user_email = _service.users().getProfile(userId="me").execute().get("emailAddress")
        except Exception:
            _user_email = None
        return _service


def gmail_permalink(thread_id):
    return f"https://mail.google.com/mail/u/0/#all/{thread_id}"


# ----------------------------------------------------------------------------
# Message parsing helpers
# ----------------------------------------------------------------------------
def _header(headers, name):
    for h in headers:
        if h.get("name", "").lower() == name.lower():
            return h.get("value", "")
    return ""


def _parse_addr(value):
    # "Jane Doe <jane@x.com>" -> ("Jane Doe", "jane@x.com")
    m = re.match(r"\s*\"?([^\"<]*)\"?\s*<([^>]+)>", value or "")
    if m:
        name = m.group(1).strip() or m.group(2).strip()
        return name, m.group(2).strip()
    return (value or "").strip(), (value or "").strip()


def _fmt_time(date_str):
    try:
        dt = parsedate_to_datetime(date_str)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        local = dt.astimezone()
        now = datetime.now().astimezone()
        if local.date() == now.date():
            return local.strftime("%-I:%M %p")
        if (now.date() - local.date()).days == 1:
            return "Yesterday"
        if local.year == now.year:
            return local.strftime("%b %-d")
        return local.strftime("%b %-d, %Y")
    except Exception:
        return ""


def _bundle_for(labels, subject, sender, snippet):
    blob = f"{subject} {sender} {snippet}"
    if TRAVEL_RE.search(blob):
        return "Travel"
    if PURCHASE_RE.search(blob):
        return "Purchases"
    if FINANCE_RE.search(blob):
        return "Finance"
    for lbl in labels:
        if lbl in CATEGORY_BUNDLES:
            return CATEGORY_BUNDLES[lbl]
    return None  # Primary / main list


def _decode_body(payload):
    """Return (text, html) walking the MIME tree."""
    text, html = "", ""

    def walk(part):
        nonlocal text, html
        mime = part.get("mimeType", "")
        body = part.get("body", {})
        data = body.get("data")
        if mime == "text/plain" and data and not text:
            text = base64.urlsafe_b64decode(data).decode("utf-8", "replace")
        elif mime == "text/html" and data:
            html = base64.urlsafe_b64decode(data).decode("utf-8", "replace")
        for sub in part.get("parts", []) or []:
            walk(sub)

    walk(payload)
    return text, html


def thread_summary(msg):
    """Build a list-row summary from a metadata message resource."""
    headers = msg.get("payload", {}).get("headers", [])
    sender_name, sender_email = _parse_addr(_header(headers, "From"))
    subject = _header(headers, "Subject") or "(no subject)"
    labels = msg.get("labelIds", [])
    snippet = msg.get("snippet", "")
    return {
        "id": msg.get("threadId"),
        "messageId": msg.get("id"),
        "sender": sender_name,
        "senderEmail": sender_email,
        "subject": subject,
        "snippet": snippet,
        "time": _fmt_time(_header(headers, "Date")),
        "ts": msg.get("internalDate", "0"),
        "unread": "UNREAD" in labels,
        "pinned": "STARRED" in labels,
        "bundle": _bundle_for(labels, subject, sender_name, snippet),
        "permalink": gmail_permalink(msg.get("threadId")),
    }


# ----------------------------------------------------------------------------
# Gmail operations
# ----------------------------------------------------------------------------
def fetch_inbox(max_results=60):
    svc = get_service()
    resp = svc.users().messages().list(
        userId="me", labelIds=["INBOX"], maxResults=max_results
    ).execute()
    ids = [m["id"] for m in resp.get("messages", [])]
    if not ids:
        return []
    rows = {}
    batch = svc.new_batch_http_request()

    def cb(request_id, response, exception):
        if exception or not response:
            return
        rows[request_id] = response

    for mid in ids:
        batch.add(
            svc.users().messages().get(
                userId="me", id=mid, format="metadata",
                metadataHeaders=["From", "Subject", "Date"],
            ),
            request_id=mid,
            callback=cb,
        )
    batch.execute()

    # newest message per thread
    by_thread = {}
    for mid in ids:
        msg = rows.get(mid)
        if not msg:
            continue
        tid = msg.get("threadId")
        prev = by_thread.get(tid)
        if not prev or int(msg.get("internalDate", 0)) > int(prev.get("internalDate", 0)):
            by_thread[tid] = msg
    summaries = [thread_summary(m) for m in by_thread.values()]
    summaries.sort(key=lambda r: int(r["ts"]), reverse=True)
    return summaries


def fetch_thread(thread_id):
    svc = get_service()
    thread = svc.users().threads().get(userId="me", id=thread_id, format="full").execute()
    messages = []
    last_rfc_id = ""
    subject = ""
    for m in thread.get("messages", []):
        headers = m.get("payload", {}).get("headers", [])
        name, email_addr = _parse_addr(_header(headers, "From"))
        subject = subject or _header(headers, "Subject")
        text, html = _decode_body(m.get("payload", {}))
        last_rfc_id = _header(headers, "Message-ID") or last_rfc_id
        messages.append({
            "id": m.get("id"),
            "sender": name,
            "senderEmail": email_addr,
            "to": _header(headers, "To"),
            "date": _fmt_time(_header(headers, "Date")),
            "text": text,
            "html": html,
            "unread": "UNREAD" in m.get("labelIds", []),
        })
    return {
        "id": thread_id,
        "subject": subject or "(no subject)",
        "messages": messages,
        "rfcMessageId": last_rfc_id,
        "permalink": gmail_permalink(thread_id),
        "pinned": "STARRED" in (thread.get("messages", [{}])[-1].get("labelIds", [])),
    }


def modify_thread(thread_id, add=None, remove=None):
    svc = get_service()
    body = {}
    if add:
        body["addLabelIds"] = add
    if remove:
        body["removeLabelIds"] = remove
    return svc.users().threads().modify(userId="me", id=thread_id, body=body).execute()


def ensure_label(name):
    svc = get_service()
    labels = svc.users().labels().list(userId="me").execute().get("labels", [])
    for l in labels:
        if l["name"] == name:
            return l["id"]
    created = svc.users().labels().create(
        userId="me",
        body={"name": name, "labelListVisibility": "labelShow",
              "messageListVisibility": "show"},
    ).execute()
    return created["id"]


def mark_read(thread_id):
    try:
        modify_thread(thread_id, remove=["UNREAD"])
    except Exception:
        pass


def send_message(to, subject, body, thread_id=None, in_reply_to=None):
    svc = get_service()
    msg = EmailMessage()
    msg["To"] = to
    msg["Subject"] = subject
    if _user_email:
        msg["From"] = _user_email
    if in_reply_to:
        msg["In-Reply-To"] = in_reply_to
        msg["References"] = in_reply_to
    msg.set_content(body)
    raw = base64.urlsafe_b64encode(msg.as_bytes()).decode()
    send_body = {"raw": raw}
    if thread_id:
        send_body["threadId"] = thread_id
    return svc.users().messages().send(userId="me", body=send_body).execute()


# ----------------------------------------------------------------------------
# Snooze scheduler
# ----------------------------------------------------------------------------
def db():
    conn = sqlite3.connect(DB_PATH)
    conn.execute("CREATE TABLE IF NOT EXISTS snoozed (thread_id TEXT PRIMARY KEY, wake_at INTEGER)")
    return conn


def snooze_thread(thread_id, wake_epoch):
    ensure_label("Snoozed")
    modify_thread(thread_id, add=[ensure_label("Snoozed")], remove=["INBOX"])
    conn = db()
    conn.execute("INSERT OR REPLACE INTO snoozed VALUES (?,?)", (thread_id, int(wake_epoch)))
    conn.commit()
    conn.close()


def _scheduler_loop():
    while True:
        try:
            now = int(time.time())
            conn = db()
            due = conn.execute("SELECT thread_id FROM snoozed WHERE wake_at <= ?", (now,)).fetchall()
            for (tid,) in due:
                try:
                    snoozed_id = ensure_label("Snoozed")
                    modify_thread(tid, add=["INBOX"], remove=[snoozed_id])
                except Exception:
                    pass
                conn.execute("DELETE FROM snoozed WHERE thread_id=?", (tid,))
            conn.commit()
            conn.close()
        except Exception:
            pass
        time.sleep(60)


# ----------------------------------------------------------------------------
# Snooze preset resolution (Inbox-style)
# ----------------------------------------------------------------------------
def resolve_snooze(preset):
    from datetime import timedelta
    now = datetime.now().astimezone()
    if preset == "later_today":
        target = now + timedelta(hours=3)
    elif preset == "tomorrow":
        target = (now + timedelta(days=1)).replace(hour=8, minute=0, second=0, microsecond=0)
    elif preset == "this_weekend":
        days = (5 - now.weekday()) % 7  # Saturday
        days = days or 7
        target = (now + timedelta(days=days)).replace(hour=8, minute=0, second=0, microsecond=0)
    elif preset == "next_week":
        days = (7 - now.weekday()) % 7 or 7
        target = (now + timedelta(days=days)).replace(hour=8, minute=0, second=0, microsecond=0)
    else:
        target = now + timedelta(hours=3)
    return int(target.timestamp())


# ----------------------------------------------------------------------------
# Routes — pages
# ----------------------------------------------------------------------------
@app.route("/")
def index():
    return render_template("index.html", open_thread="")


@app.route("/thread/<thread_id>")
def open_thread_route(thread_id):
    """Deep-link target. If the thread can't be served, fall back to Gmail."""
    gmail_fallback = request.args.get("gmail") or gmail_permalink(thread_id)
    try:
        get_service()
        fetch_thread(thread_id)  # verify it exists / is reachable
    except Exception:
        return redirect(gmail_fallback)
    return render_template("index.html", open_thread=thread_id)


# ----------------------------------------------------------------------------
# Routes — API
# ----------------------------------------------------------------------------
@app.route("/api/health")
def api_health():
    authed = os.path.exists(TOKEN_PATH)
    return jsonify({"ok": True, "authed": authed, "email": _user_email})


@app.route("/api/inbox")
def api_inbox():
    try:
        rows = fetch_inbox()
    except Exception as e:
        return jsonify({"error": str(e)}), 500
    pinned = [r for r in rows if r["pinned"]]
    primary = [r for r in rows if not r["bundle"] and not r["pinned"]]
    bundles = {}
    for r in rows:
        if r["pinned"]:
            continue
        if r["bundle"]:
            bundles.setdefault(r["bundle"], []).append(r)
    bundle_list = []
    for name in BUNDLE_ORDER:
        if name in bundles:
            bundle_list.append({
                "name": name,
                "icon": BUNDLE_META[name]["icon"],
                "color": BUNDLE_META[name]["color"],
                "count": len(bundles[name]),
                "items": bundles[name],
            })
    return jsonify({"pinned": pinned, "primary": primary, "bundles": bundle_list,
                    "email": _user_email})


@app.route("/api/thread/<thread_id>")
def api_thread(thread_id):
    try:
        data = fetch_thread(thread_id)
        mark_read(thread_id)
        return jsonify(data)
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/done", methods=["POST"])
def api_done():
    tid = request.json["threadId"]
    modify_thread(tid, remove=["INBOX"])
    return jsonify({"ok": True})


@app.route("/api/undo_done", methods=["POST"])
def api_undo_done():
    tid = request.json["threadId"]
    modify_thread(tid, add=["INBOX"])
    return jsonify({"ok": True})


@app.route("/api/pin", methods=["POST"])
def api_pin():
    tid = request.json["threadId"]
    if request.json.get("pinned"):
        modify_thread(tid, add=["STARRED"])
    else:
        modify_thread(tid, remove=["STARRED"])
    return jsonify({"ok": True})


@app.route("/api/snooze", methods=["POST"])
def api_snooze():
    tid = request.json["threadId"]
    preset = request.json.get("preset", "later_today")
    wake = request.json.get("epoch") or resolve_snooze(preset)
    snooze_thread(tid, wake)
    return jsonify({"ok": True, "wake": wake})


@app.route("/api/send", methods=["POST"])
def api_send():
    d = request.json
    try:
        send_message(d["to"], d.get("subject", ""), d.get("body", ""),
                     thread_id=d.get("threadId"), in_reply_to=d.get("inReplyTo"))
        return jsonify({"ok": True})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


@app.route("/api/to_things", methods=["POST"])
def api_to_things():
    d = request.json
    tid = d["threadId"]
    title = d.get("title", "(email)")
    sender = d.get("sender", "")
    snippet = d.get("snippet", "")
    permalink = gmail_permalink(tid)
    backlink = f"inboxclone://thread/{tid}?gmail={quote(permalink, safe='')}"
    notes = f"{backlink}\n\nGmail (fallback): {permalink}\n\nFrom: {sender}\n{snippet}"
    things = f"things:///add?title={quote(title)}&notes={quote(notes)}"
    try:
        subprocess.run(["open", things], check=True)
        return jsonify({"ok": True})
    except Exception as e:
        return jsonify({"error": str(e), "url": things}), 500


if __name__ == "__main__":
    threading.Thread(target=_scheduler_loop, daemon=True).start()
    # Trigger auth before serving so the consent flow opens cleanly on first run
    try:
        get_service()
    except Exception as e:
        print(f"[auth] deferred: {e}")
    app.run(host="127.0.0.1", port=PORT, debug=False)

/* Inbox by Gmail — reconstructed tokens (see design spec) */
:root{
  --inbox-blue:#4285F4;
  --inbox-blue-dark:#3367D6;
  --fab-red:#d23f31;
  --done-green:#0F9D58;
  --bg-page:#F2F2F2;
  --bg-card:#FFFFFF;
  --divider:#DDDDDD;
  --text-primary:#212121;
  --text-secondary:#5F6368;
  --shadow-card:0 1px 2px 0 rgba(0,0,0,.10),0 1px 3px 0 rgba(0,0,0,.08);
  --shadow-fab:0 6px 10px 0 rgba(0,0,0,.14),0 1px 18px 0 rgba(0,0,0,.12),0 3px 5px -1px rgba(0,0,0,.2);
}
*{box-sizing:border-box}
html,body{margin:0;height:100%}
body{font-family:Roboto,Arial,sans-serif;background:var(--bg-page);color:var(--text-primary);font-size:14px}

/* App bar */
.appbar{height:56px;background:var(--inbox-blue);color:#fff;display:flex;align-items:center;
  padding:0 8px;gap:8px;position:sticky;top:0;z-index:30;box-shadow:0 1px 4px rgba(0,0,0,.2)}
.appbar .icon-btn{color:#fff}
.wordmark{font-size:20px;font-weight:400;margin:0 8px;letter-spacing:.2px}
.search{flex:1;max-width:680px;background:rgba(255,255,255,.18);border-radius:4px;height:36px;
  display:flex;align-items:center;padding:0 10px;gap:8px;color:#fff}
.search input{flex:1;border:0;background:transparent;color:#fff;font-size:15px;outline:none}
.search input::placeholder{color:rgba(255,255,255,.85)}
.search .material-icons{font-size:20px}
.pinned-toggle{display:flex;align-items:center;cursor:pointer;opacity:.9}
.pinned-toggle input{margin-left:2px}
.icon-btn{background:none;border:0;cursor:pointer;width:40px;height:40px;border-radius:50%;
  display:inline-flex;align-items:center;justify-content:center;color:var(--text-secondary)}
.icon-btn:hover{background:rgba(0,0,0,.06)}
.appbar .icon-btn:hover{background:rgba(255,255,255,.15)}

/* Layout */
.layout{display:flex;align-items:flex-start}
.drawer{width:256px;flex-shrink:0;padding:8px 0;position:sticky;top:56px;height:calc(100vh - 56px);overflow:auto}
.drawer-acct{padding:8px 24px 16px;color:var(--text-secondary);font-size:13px;word-break:break-all}
.nav-item{display:flex;align-items:center;gap:18px;height:44px;padding:0 24px;cursor:pointer;
  color:var(--text-secondary);border-radius:0 22px 22px 0;margin-right:10px;font-weight:500;text-decoration:none}
.nav-item .material-icons{font-size:20px}
.nav-item:hover{background:rgba(0,0,0,.05)}
.nav-item.active{background:#FCE8E6;color:var(--fab-red)}
.nav-item.active .material-icons{color:var(--fab-red)}
.nav-sep{padding:14px 24px 6px;font-size:11px;text-transform:uppercase;color:#9aa0a6;letter-spacing:.6px}

/* Content */
.content{flex:1;max-width:840px;margin:16px auto;padding:0 16px;width:100%}
.loading{padding:40px;text-align:center;color:var(--text-secondary)}
.section-label{font-size:12px;color:var(--text-secondary);margin:16px 4px 8px;font-weight:500}
.empty{text-align:center;color:var(--text-secondary);padding:80px 0}
.empty .material-icons{font-size:72px;color:#F4C20D}
.empty p{font-size:18px;font-weight:300}

/* Cards */
.card{background:var(--bg-card);border:1px solid var(--divider);border-radius:8px;margin-bottom:8px;
  box-shadow:var(--shadow-card);display:flex;align-items:flex-start;padding:14px 16px;gap:12px;
  cursor:pointer;position:relative;transition:transform .18s ease,opacity .18s ease}
.card:hover{box-shadow:0 1px 3px rgba(0,0,0,.2),0 1px 8px rgba(0,0,0,.12)}
.card.swiping{transition:none}
.card .avatar{width:40px;height:40px;border-radius:50%;background:var(--inbox-blue);color:#fff;
  display:flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0;font-weight:500}
.card .body{flex:1;min-width:0}
.card .row1{display:flex;justify-content:space-between;align-items:baseline;gap:8px}
.card .sender{font-size:14px;color:var(--text-primary)}
.card.unread .sender,.card.unread .subject{font-weight:500}
.card .time{font-size:12px;color:var(--text-secondary);flex-shrink:0}
.card .subject{font-size:14px;color:var(--text-primary);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.card .snippet{font-size:13px;color:var(--text-secondary);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.card .actions{position:absolute;right:10px;top:8px;display:none;gap:2px;background:var(--bg-card);padding-left:6px}
.card:hover .actions{display:flex}
.card .actions .icon-btn{width:34px;height:34px}
.card.unread::before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--inbox-blue);border-radius:8px 0 0 8px}
.pin-dot{color:#F4B400;font-size:18px}

/* Bundle row */
.bundle{background:var(--bg-card);border:1px solid var(--divider);border-radius:8px;margin-bottom:8px;
  box-shadow:var(--shadow-card);overflow:hidden}
.bundle-head{display:flex;align-items:center;gap:14px;padding:14px 16px;cursor:pointer}
.bundle-head .bicon{width:36px;height:36px;border-radius:50%;display:flex;align-items:center;justify-content:center;color:#fff}
.bundle-head .bname{font-weight:500;font-size:14px}
.bundle-head .bcount{color:var(--text-secondary);font-size:13px;margin-left:6px}
