async function load() {
  $("#loading").hidden = false;
  $("#loading").textContent = "Loading…";
  const v = STATE.view;
  let d;
  if (v === "inbox") {
    d = await api("/api/inbox");
    STATE.inboxCache = d;
  } else if (v === "pinned") {
    const i = await api("/api/inbox");
    STATE.inboxCache = i;
    d = { items: i.pinned || [], email: i.email };
  } else if (v === "snoozed") {
    d = await api("/api/snoozed");
