# ----------------------------------------------------------------------------
# Live sync — poll Gmail's History API for deltas, push to browsers via SSE
# ----------------------------------------------------------------------------
POLL_INTERVAL = 8  # seconds
SYNC = {"version": 0, "history_id": None}


def _history_loop():
    from googleapiclient.errors import HttpError
    while True:
        try:
            svc = get_service()
            if SYNC["history_id"] is None:
                SYNC["history_id"] = svc.users().getProfile(userId="me").execute().get("historyId")
            else:
                try:
                    resp = svc.users().history().list(
                        userId="me", startHistoryId=SYNC["history_id"],
                        historyTypes=["messageAdded", "labelAdded", "labelRemoved"],
                    ).execute()
                    if resp.get("history"):
                        SYNC["version"] += 1  # something changed -> tell the browser
                    SYNC["history_id"] = resp.get("historyId", SYNC["history_id"])
                except HttpError as he:
                    # 404 = startHistoryId too old; reset cursor and force a refresh
                    if getattr(he, "resp", None) is not None and he.resp.status == 404:
                        SYNC["history_id"] = svc.users().getProfile(userId="me").execute().get("historyId")
                        SYNC["version"] += 1
                    else:
                        raise
        except Exception:
            pass
        time.sleep(POLL_INTERVAL)

