@app.route("/api/drafts")
def api_drafts():
    limit = _limit_arg()
    try:
        svc = get_service()
        drafts = _exec(svc.users().drafts().list(userId="me", maxResults=limit)).get("drafts", [])
        mid_to_did, ids = {}, []
        for dr in drafts:
            mid = (dr.get("message") or {}).get("id")
            if mid:
                mid_to_did[mid] = dr["id"]
                ids.append(mid)
        rows = {}

        def cb(rid, resp, exc):
            if not exc and resp:
                rows[rid] = resp
        for i in range(0, len(ids), 50):
            batch = svc.new_batch_http_request()
            for mid in ids[i:i + 50]:
                batch.add(svc.users().messages().get(
                    userId="me", id=mid, format="metadata",
                    metadataHeaders=["To", "Subject", "Date"]), request_id=mid, callback=cb)
            with API_LOCK:
                batch.execute()
        items = []
        for mid in ids:
            msg = rows.get(mid)
            if not msg:
                continue
            headers = msg.get("payload", {}).get("headers", [])
            to_name, _ = _parse_addr(_header(headers, "To"))
            items.append({
                "draftId": mid_to_did[mid], "messageId": mid, "draft": True,
                "sender": ("To: " + (to_name or "(no recipient)")),
                "subject": _header(headers, "Subject") or "(no subject)",
                "snippet": msg.get("snippet", ""),
                "time": _fmt_time(_header(headers, "Date")),
                "ts": msg.get("internalDate", "0"),
            })
        items.sort(key=lambda r: int(r["ts"]), reverse=True)
        return jsonify({"items": items, "email": _user_email, "fetched": len(items), "nextPageToken": None})
    except Exception as e:
        return jsonify({"error": str(e)}), 500


