_RATE_REASONS = {"rateLimitExceeded", "userRateLimitExceeded", "quotaExceeded", "backendError"}


def _is_retryable(exc):
    """True for transient Gmail errors worth backing off on (rate limits, 5xx, sockets)."""
    if isinstance(exc, HttpError):
        status = getattr(getattr(exc, "resp", None), "status", None)
        if status in (429, 500, 502, 503, 504):
            return True
        if status == 403:
            # Only retry rate/quota 403s — NOT auth/permission 403s (those won't fix themselves).
            blob = exc.content or b""
            try:
                reasons = {e.get("reason") for e in
                           json.loads(blob.decode("utf-8")).get("error", {}).get("errors", [])}
                if reasons & _RATE_REASONS:
                    return True
            except Exception:
                pass
            return b"rateLimitExceeded" in blob or b"Quota exceeded" in blob
        return False
    return isinstance(exc, (TimeoutError, ConnectionError, OSError))


def _run_with_retry(thunk, tries=6, base=1.0, cap=32.0):
    """Call thunk(), backing off exponentially (with jitter) on transient/rate-limit errors."""
    for attempt in range(tries):
        try:
            return thunk()
        except Exception as e:  # noqa: BLE001 — re-raised below unless retryable
            if attempt == tries - 1 or not _is_retryable(e):
                raise
            time.sleep(min(cap, base * (2 ** attempt)) + random.uniform(0, 0.5))


